#!/usr/bin/env bash\nset -e\n\n# Mock rationale: Use local backend and dummy variables to validate module without AWS calls.\n\n# Initialize Terraform with no backend\nterraform init -backend=false > /dev/null\n\n# Validate configuration\nterraform validate\n\n# Run a plan with dummy values\nterraform plan -var=\"bucket_name=test-safehouse-bucket\" -var=\"iam_role_name=test-role\" -out=plan.out > plan.out\n\n# Check that plan contains the bucket resource\nif ! grep -q "aws_s3_bucket.safehouse" plan.out; then\n  echo "Plan does not contain expected S3 bucket resource"\n  exit 1\nfi\n\necho "All tests passed."
